from azure.identity import DefaultAzureCredential
from azure.keyvault.keys.crypto import CryptographyClient, EncryptionAlgorithm

def decrypt_payload(ciphertext, config=None):
    config = config or {}
    with DefaultAzureCredential() as credential:
        with CryptographyClient(config['key_id'], credential=credential) as client:
            response = client.decrypt(EncryptionAlgorithm.a256_gcm, ciphertext['ciphertext'], ciphertext['iv'], ciphertext['tag'])
    return {'plaintext': response.plaintext, 'key_id': response.key_id, 'algorithm': 'A256GCM'}

from azure.identity import DefaultAzureCredential
from azure.keyvault.keys.crypto import CryptographyClient, EncryptionAlgorithm

def envelope_encrypt(plaintext, config=None):
    config = config or {}
    with DefaultAzureCredential() as credential:
        with CryptographyClient(config['key_id'], credential=credential) as client:
            response = client.encrypt(EncryptionAlgorithm.a256_gcm, plaintext)
            data_encryption_key = response.ciphertext
            response = client.encrypt(EncryptionAlgorithm.a256_gcm, data_encryption_key)
            return {'ciphertext': response.ciphertext, 'iv': response.iv, 'tag': response.authentication_tag,
                    'key_id': response.key_id, 'algorithm': 'A256GCM'}

from azure.identity import DefaultAzureCredential
from azure.keyvault.keys.crypto import CryptographyClient, SignatureAlgorithm

def sign_or_verify_key(payload, config=None):
    config = config or {}
    with DefaultAzureCredential() as credential:
        with CryptographyClient(config['key_id'], credential=credential) as client:
            response = client.sign(SignatureAlgorithm.rsassa_pss, payload)
            return {'signature': response.signature, 'key_id': response.key_id, 'algorithm': 'RS256'}

